import 'package:dio/dio.dart';import '../../../../../../Core/Storage/Local/local_storage_keys.dart';import '../../../../../../Core/Storage/Local/local_storage_service.dart';import '../../../../../Global/Authentication/data/Models/user_data_model.dart';import '../models/update_password.dart';import '../models/update_user.dart';import '../../../../../../Core/Storage/Remote/api_endpoints.dart';import '../../../../../../Core/Storage/Remote/api_service.dart';class UserDataSources {  static Future<UpdateUser> updateUserData(      {required UpdateUser updateUser}) async {    final response = await DioHelper.postData(      data: updateUser.toMap(),      path: ApiEndpoints.updateUser,    );    return UpdateUser.fromMap(response.data["data"]);  }  static Future<bool> updatePassword({required UpdatePassword updateUser}) async {    final response = await DioHelper.postData(      data: updateUser.toMap(),      path: ApiEndpoints.changePassword,    );    if (response.statusCode != 200) {      return false;    }    return true;  }  static Future<UserDataModel> getUserData() async {    final response = await DioHelper.getData(      path: ApiEndpoints.getUser,    );    return UserDataModel.fromJson((response.data["user"]));  }  static Future<UserDataModel> refreshToken() async {    String? token = LocalStorageService.getValue(LocalStorageKeys.token);    final options = Options(headers: {      'Authorization': token != null && token.isNotEmpty ? 'Bearer $token' : '',    });    final response = await DioHelper.postData(      options:options ,      path: ApiEndpoints.refreshToken,    );    return UserDataModel.fromJson((response.data["user"]));  }}